import test from "node:test";
import assert from "node:assert/strict";
import path from "node:path";
import { cli, project, tmp, readJson } from "./helpers.mjs";

const files = {
  "README.md": "# Hello\n\nWorld text here.\n",
  "docs/guide.md": "# Guide\n\nUse it.\n",
  "src/app.go": "package app\n\nfunc Run() {}\n",
  "src/app_test.go": "package app\n\nfunc TestRun() {}\n",
  "src/gen.pb.go": "// Code generated by protoc. DO NOT EDIT.\npackage app\n\nfunc G() {}\n",
  "src/web/index.ts": "export const a = 1;\n",
  "src/web/index.test.ts": "test('x', () => {});\n",
  "node_modules/lib/index.js": "module.exports = 1;\n",
  "dist/bundle.js": "var a=1;\n",
  "static/app.min.js": "var a=1;\n",
  "go.sum": "abc h1:xyz\n",
  "package-lock.json": "{}\n",
  "deploy.pem": "-----BEGIN KEY-----\n",
  "id_rsa": "private\n",
  "prod.tfvars": "pw = 1\n",
  ".env": "TOKEN=abc\n",
  ".hidden/notes.md": "# secret notes\n\ntext\n",
  "config/app.yaml": "a: 1\n",
  "testdata/golden.md": "# golden\n\nfixture\n",
  "image.png": "PNG\u0000\u0000binary",
  "ignored.md": "# ignored by git\n\ntext\n",
  "blob.go": "package x\n\n" + "// ".padEnd(400 * 1024, "x") + "\n",
};
const ignore = "ignored.md\n";

function sel(extra = []) {
  const dir = project(files, { ignore }), work = path.join(tmp(), "w");
  const r = cli(["split", dir, "--work", work, ...extra]);
  assert.equal(r.code, 0, r.out);
  const S = readJson(path.join(work, "selection.json"));
  return { included: new Set(S.included), reasons: S.reasons, out: r.out };
}

test("default selection keeps meaningful files and honours .gitignore", () => {
  const { included } = sel();
  for (const f of ["README.md", "docs/guide.md", "src/app.go", "src/web/index.ts"]) assert.ok(included.has(f), `${f} should be included`);
  for (const f of ["ignored.md", "node_modules/lib/index.js", "dist/bundle.js", "static/app.min.js", "go.sum", "package-lock.json", "image.png", "src/gen.pb.go", "blob.go"])
    assert.ok(!included.has(f), `${f} should be skipped`);
});

test("secrets, hidden files, fixtures, tests and config are skipped by default", () => {
  const { included } = sel();
  for (const f of ["deploy.pem", "id_rsa", "prod.tfvars", ".env", ".hidden/notes.md", "testdata/golden.md", "src/app_test.go", "src/web/index.test.ts", "config/app.yaml"])
    assert.ok(!included.has(f), `${f} should be skipped`);
});

test("skips are reported with a reason and an example", () => {
  const { reasons, out } = sel();
  assert.ok(Object.keys(reasons).some(r => /secret/.test(r)), JSON.stringify(reasons));
  assert.match(out, /skipped\s+\d+\s+test file/);
  assert.match(out, /skipped\s+\d+\s+config file/);
  assert.match(out, /estimate: ~\d+ haiku agents/);
});

test("--tests and --config opt in", () => {
  const { included } = sel(["--tests", "--config"]);
  assert.ok(included.has("src/app_test.go") && included.has("src/web/index.test.ts"));
  assert.ok(included.has("config/app.yaml"));
  assert.ok(!included.has("deploy.pem"), "secrets stay out even with --config");
});

test("--exclude removes and --include forces files in", () => {
  const a = sel(["--exclude", "docs/**"]);
  assert.ok(!a.included.has("docs/guide.md"));
  const b = sel(["--include", "deploy.pem"]);
  assert.ok(b.included.has("deploy.pem"), "explicit include overrides the secret filter");
  const c = sel(["--max-kb", "1000"]);
  assert.ok(c.included.has("blob.go"));
});

test("a directory that is not a git repo is walked, skipping hidden and vendored dirs", () => {
  const dir = project(files, { git: false }), work = path.join(tmp(), "w");
  const r = cli(["split", dir, "--work", work]);
  assert.equal(r.code, 0, r.out);
  const S = readJson(path.join(work, "selection.json"));
  assert.ok(S.included.includes("README.md") && S.included.includes("src/app.go"));
  assert.ok(!S.included.some(f => f.startsWith("node_modules/") || f.startsWith(".hidden/")));
});

test("markdown over the source size cap is still included (docs are split, not skipped)", () => {
  const big = "# Big\n\n" + Array.from({ length: 6000 }, (_, i) => `- line ${i} ${"padding ".repeat(8)}`).join("\n") + "\n";
  const dir = project({ "BIG.md": big }), work = path.join(tmp(), "w");
  const r = cli(["split", dir, "--work", work]);
  assert.equal(r.code, 0, r.out);
  assert.deepEqual(readJson(path.join(work, "selection.json")).included, ["BIG.md"]);
});

test("test directories (tests/, __tests__/, e2e/) are skipped by default, like test file names; --tests brings them back", () => {
  const f = { "src/app.go": "package a\n\nfunc A() {}\n", "tests/helper.go": "package t\n\nfunc H() {}\n", "pkg/__tests__/a.js": "export const a = 1;\n", "e2e/flow.ts": "export const f = 1;\n", "src/test_util.py": "def t(): pass\n", "docs/testing.md": "# Testing\n\nHow we test.\n" };
  const dir = project(f), run = extra => { const work = path.join(tmp(), "w"); assert.equal(cli(["split", dir, "--work", work, ...extra]).code, 0); return new Set(readJson(path.join(work, "selection.json")).included); };
  const d = run([]);
  assert.deepEqual([...d].sort(), ["docs/testing.md", "src/app.go"]);
  assert.equal(run(["--tests"]).size, 6);
});

test("nothing selected is an error, not a cost estimate of -Infinity", () => {
  const dir = project({ "image.png": "PNG\u0000", "go.sum": "x\n" }), work = path.join(tmp(), "w");
  const r = cli(["split", dir, "--work", work]);
  assert.equal(r.code, 1); assert.match(r.out, /nothing to analyse/); assert.ok(!/Infinity|NaN/.test(r.out));
});
